-- name: CreateOrchestrationCommandSubmission :one
INSERT INTO orchestration_command_submissions (command_id, command_version, submission_id, subject_selector, caller_principal_ref, scope_ref, source_fence_ref, target_fence_ref, idempotency_namespace, idempotency_key_digest, request_digest, pending_cursor, pending_cursor_digest, accept_resolution, resolution_kind, revision)
VALUES (sqlc.arg(command_id), 1, sqlc.arg(submission_id), sqlc.arg(subject_selector), sqlc.arg(caller_principal_ref), sqlc.arg(scope_ref), sqlc.arg(source_fence_ref), sqlc.arg(target_fence_ref), sqlc.arg(idempotency_namespace), sqlc.arg(idempotency_key_digest), sqlc.arg(request_digest), sqlc.arg(pending_cursor), sqlc.arg(pending_cursor_digest), 'pending', 'pending', 1)
ON CONFLICT(idempotency_namespace, idempotency_key_digest) DO NOTHING
RETURNING command_id, command_version, submission_id, subject_selector, caller_principal_ref, scope_ref, source_fence_ref, target_fence_ref, idempotency_namespace, idempotency_key_digest, request_digest, pending_cursor, pending_cursor_digest, accept_resolution, resolution_kind, accept_receipt_ref, accept_receipt_digest, reject_receipt_ref, reject_receipt_digest, recovery_receipt_ref, recovery_receipt_digest, accepted_command_fence_ref, accepted_command_fence_digest, accepted_command_fence_cursor, rejected_command_fence_ref, rejected_command_fence_digest, rejected_command_fence_cursor, revision, recorded_at, updated_at;

-- name: GetOrchestrationCommandSubmissionByKey :one
SELECT command_id, command_version, submission_id, subject_selector, caller_principal_ref, scope_ref, source_fence_ref, target_fence_ref, idempotency_namespace, idempotency_key_digest, request_digest, pending_cursor, pending_cursor_digest, accept_resolution, resolution_kind, accept_receipt_ref, accept_receipt_digest, reject_receipt_ref, reject_receipt_digest, recovery_receipt_ref, recovery_receipt_digest, accepted_command_fence_ref, accepted_command_fence_digest, accepted_command_fence_cursor, rejected_command_fence_ref, rejected_command_fence_digest, rejected_command_fence_cursor, revision, recorded_at, updated_at FROM orchestration_command_submissions WHERE idempotency_namespace = sqlc.arg(idempotency_namespace) AND idempotency_key_digest = sqlc.arg(idempotency_key_digest);

-- name: GetOrchestrationCommandSubmissionByID :one
SELECT command_id, command_version, submission_id, subject_selector, caller_principal_ref, scope_ref, source_fence_ref, target_fence_ref, idempotency_namespace, idempotency_key_digest, request_digest, pending_cursor, pending_cursor_digest, accept_resolution, resolution_kind, accept_receipt_ref, accept_receipt_digest, reject_receipt_ref, reject_receipt_digest, recovery_receipt_ref, recovery_receipt_digest, accepted_command_fence_ref, accepted_command_fence_digest, accepted_command_fence_cursor, rejected_command_fence_ref, rejected_command_fence_digest, rejected_command_fence_cursor, revision, recorded_at, updated_at FROM orchestration_command_submissions WHERE command_id = sqlc.arg(command_id) AND submission_id = sqlc.arg(submission_id);

-- name: ResolveOrchestrationCommandSubmission :one
UPDATE orchestration_command_submissions SET accept_resolution = sqlc.arg(accept_resolution), resolution_kind = sqlc.arg(resolution_kind), accept_receipt_ref = sqlc.arg(accept_receipt_ref), accept_receipt_digest = sqlc.arg(accept_receipt_digest), reject_receipt_ref = sqlc.arg(reject_receipt_ref), reject_receipt_digest = sqlc.arg(reject_receipt_digest), recovery_receipt_ref = sqlc.arg(recovery_receipt_ref), recovery_receipt_digest = sqlc.arg(recovery_receipt_digest), accepted_command_fence_ref = sqlc.arg(accepted_command_fence_ref), accepted_command_fence_digest = sqlc.arg(accepted_command_fence_digest), accepted_command_fence_cursor = sqlc.arg(accepted_command_fence_cursor), rejected_command_fence_ref = sqlc.arg(rejected_command_fence_ref), rejected_command_fence_digest = sqlc.arg(rejected_command_fence_digest), rejected_command_fence_cursor = sqlc.arg(rejected_command_fence_cursor), revision = revision + 1, updated_at = strftime('%Y-%m-%dT%H:%M:%fZ', 'now') WHERE command_id = sqlc.arg(command_id) AND submission_id = sqlc.arg(submission_id) AND command_version = sqlc.arg(command_version) AND pending_cursor = sqlc.arg(pending_cursor) AND pending_cursor_digest = sqlc.arg(pending_cursor_digest) AND revision = sqlc.arg(expected_revision) AND accept_resolution = 'pending'
RETURNING command_id, command_version, submission_id, subject_selector, caller_principal_ref, scope_ref, source_fence_ref, target_fence_ref, idempotency_namespace, idempotency_key_digest, request_digest, pending_cursor, pending_cursor_digest, accept_resolution, resolution_kind, accept_receipt_ref, accept_receipt_digest, reject_receipt_ref, reject_receipt_digest, recovery_receipt_ref, recovery_receipt_digest, accepted_command_fence_ref, accepted_command_fence_digest, accepted_command_fence_cursor, rejected_command_fence_ref, rejected_command_fence_digest, rejected_command_fence_cursor, revision, recorded_at, updated_at;
